/** Platform-owned shared profile surface. Hosts supply only adapters. */
import { buildWataProfilePatch, normalizeWataProfile, isWataProfileComplete, isSupportedProfileAvatar } from './wata-profile.js';
import { cropProfilePhoto } from './profile-photo.js';
export { isWataProfileComplete };
export const WATA_PROFILE_COMPONENT_VERSION = '1.2.1';
export const COUNTRY_CODES = 'AF AL DZ AD AO AG AR AM AU AT AZ BS BH BD BB BY BE BZ BJ BT BO BA BW BR BN BG BF BI CV KH CM CA CF TD CL CN CO KM CD CG CR CI HR CU CY CZ DK DJ DM DO EC EG SV GQ ER EE SZ ET FJ FI FR GA GM GE DE GH GR GD GT GN GW GY HT HN HU IS IN ID IR IQ IE IL IT JM JP JO KZ KE KI KP KR KW KG LA LV LB LS LR LY LI LT LU MG MW MY MV ML MT MH MR MU MX FM MD MC MN ME MA MZ MM NA NR NP NL NZ NI NE NG MK NO OM PK PW PS PA PG PY PE PH PL PT QA RO RU RW KN LC VC WS SM ST SA SN RS SC SL SG SK SI SB SO ZA SS ES LK SD SR SE CH SY TW TJ TZ TH TL TG TO TT TN TR TM TV UG UA AE GB US UY UZ VU VA VE VN YE ZM ZW'.split(' ');
const suggestions = {
  skills:['Water systems','Project management','Photography','Grant writing','Translation','Teaching','Engineering','Design','Music','Research'],
  interests:['Travel','Surfing','Music','Cooking','Hiking','Reading','Art','Sports'],
  humanitarian_interests:['Clean water','Education','Public health','Conservation','Human rights','Community building']
};
const esc = (value='') => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const flag = code => [...code].map(c=>String.fromCodePoint(127397+c.charCodeAt(0))).join('');
const names = new Intl.DisplayNames(['en'],{type:'region'});
export function countryResults(query='') { return COUNTRY_CODES.map(code=>({code,name:names.of(code)})).filter(c=>c.name.toLowerCase().includes(query.trim().toLowerCase())).sort((a,b)=>a.name.localeCompare(b.name)); }
const icons = {person:"M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-2a8 8 0 0 1 16 0v2",pin:"M12 22S4 14 4 9a8 8 0 1 1 16 0c0 5-8 13-8 13Z M12 6a3 3 0 1 0 0 6 3 3 0 0 0 0-6",globe:"M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M3 12h18 M12 3c-5 5-5 13 0 18 M12 3c5 5 5 13 0 18",pen:'M16 3 21 8 8 21 3 21 3 16Z M13 6l5 5',save:'m5 12 4 4 10-10',plus:'M12 5v14 M5 12h14',close:'m6 6 12 12 M18 6 6 18',about:'M12 8h.01 M12 11v6 M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18',travel:'m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3Z M9 3v15 M15 6v15',learning:'m2 9 10-5 10 5-10 5Z M6 11v6q6 5 12 0v-6 M22 9v8',goals:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 11v2',contact:'M3 5h18v14H3Z m0 1 9 7 9-7',settings:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',light:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',dark:'M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11'};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]}"/></svg>`;
export function normalizeRichProfile(value={}) { return {...value,...normalizeWataProfile(value),about:value.about||value.bio||'',humanitarian_interests:[...(value.humanitarian_interests||[])],countries_visited:[...(value.countries_visited||[])],goals:(value.goals||[]).map(g=>({...g}))}; }
export function splitCurrentLocation(value='') { const parts=String(value).split(',').map(s=>s.trim());const last=parts.at(-1);const country=countryResults().find(c=>c.name.toLowerCase()===last.toLowerCase());return country?{city:parts.slice(0,-1).join(', '),country:country.name}:{city:String(value),country:''}; }
export function richProfilePatch(raw,profile,avatar) { const fields={...raw};if('current_city' in raw)fields.current_location=[String(raw.current_city||'').trim(),String(raw.current_country||'').trim()].filter(Boolean).join(', ');return {...buildWataProfilePatch(fields,profile.skills,profile.interests,avatar),about:String(raw.about||'').trim(),humanitarian_interests:profile.humanitarian_interests,countries_visited:profile.countries_visited,goals:profile.goals,show_interests:Boolean(raw.show_interests),show_humanitarian_interests:Boolean(raw.show_humanitarian_interests),show_travel:Boolean(raw.show_travel),show_goals:Boolean(raw.show_goals),suite_theme:raw.suite_theme,suite_accent:raw.suite_accent,suite_language:raw.suite_language}; }
export function geometryPath(geometry) {
  const polygons=geometry.type==='Polygon'?[geometry.coordinates]:geometry.type==='MultiPolygon'?geometry.coordinates:[];
  return polygons.map(p=>p.map(r=>{let prev=null;return r.map(([lon,lat],i)=>{const x=(lon+180)/360*960,y=(90-lat)/180*500,jump=prev!==null&&Math.abs(x-prev)>480;prev=x;return `${!i||jump?'M':'L'}${x.toFixed(1)} ${y.toFixed(1)}`;}).join(' ')+' Z';}).join(' ')).join(' ');
}
export function countryShape(geometry) {
  const polygons=geometry.type==='Polygon'?[geometry.coordinates]:geometry.type==='MultiPolygon'?geometry.coordinates:[];
  const area=p=>Math.abs(p[0].reduce((sum,[x,y],i,a)=>{const next=a[(i+1)%a.length];return sum+x*next[1]-next[0]*y;},0));
  const polygon=[...polygons].sort((a,b)=>area(b)-area(a))[0];
  if(!polygon)return '';
  const d=geometryPath({type:'Polygon',coordinates:polygon}),points=[...d.matchAll(/[ML]([\d.-]+) ([\d.-]+)/g)].map(m=>[Number(m[1]),Number(m[2])]);
  const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]);const x=Math.min(...xs),y=Math.min(...ys),w=Math.max(...xs)-x,h=Math.max(...ys)-y,pad=Math.max(w,h)*.08||1;
  return `<svg class="country-shape" viewBox="${x-pad} ${y-pad} ${w+pad*2} ${h+pad*2}" aria-hidden="true"><path d="${d}"/></svg>`;
}
