  stylesheet.addEventListener('load',reveal,{once:true});
  stylesheet.addEventListener('error',()=>{if(!destroyed)root.querySelector('#styleStatus').textContent='Profile styling could not load. Please reload before editing.';},{once:true});
  if(stylesheet.sheet)reveal();
