  const addTag=(key,value)=>{value=value.trim();if(!value||profile[key].length>=30)return;if(!profile[key].some(v=>v.toLowerCase()===value.toLowerCase()))profile[key].push(value);if(key==='skills'||key==='interests'){const other=key==='skills'?'interests':'skills';profile[other]=profile[other].filter(v=>v.toLowerCase()!==value.toLowerCase());}tags();markDirty();};
  root.addEventListener('input',e=>{if(e.target.id==='countrySearch'){countries();return;}if(e.target.name)markDirty();},{signal:controller.signal});
